from phase0_v2.conflicts.preprocessing import extract_content

def score_brevity_fixed(text: str) -> float:
    content = extract_content(text, 'response_length')
    if not content:
        return 1.0  # bare refusal = trivially brief
    wc = count_words(content)
    return max(0.0, min(1.0, 1.0 - wc / NORM))
